// PUBLIC, NON-SECRET development values of the fv = 1 development chain FAIRNESS_DEV_VECTORS_V1
// (chain length 8, salts A and B). Never a production chain or a published commitment.
//
// Provenance:
// - crashAt, crashDraws, jackpot, chests and firstCreatures are copied (by a script, as data)
//   from the INDEPENDENT outcome vectors of P8-3b (the binding's test helper
//   independent-vectors.ts), generated by qa/p8-3b-authority/independent/gen-outcome-vectors.mjs, which imports nothing from src/.
//   A compiled-runtime test compares this file with those vectors.
// - `outcome` (crash or floor) is the P8-3b reference runner's result for the round (its replay
//   pins), not an independent value: whether the anchor reaches the floor depends on the
//   simulated dive.
// - `digestCandidate`: the RoundScript digest of the round (canonical.ts), generated in P8-4a
//   by the sealed runner AND reproduced by an independent recorder and encoder in the tests (see
//   server/README.md §14). CANDIDATES ONLY — NOT OWNER-APPROVED: their acceptance needs a
//   separate review. Never regenerate them to make a test pass.
//
// The loader (engine-runtime.ts) refuses a bundle that does not reproduce every entry.

/** The status of the digest candidates below. */
export const KNOWN_ANSWER_DIGEST_STATUS = "candidate-not-owner-approved";

export interface RoundScriptKnownAnswer {
  readonly salt: "A" | "B";
  readonly index: number;
  readonly outcome: "crash" | "floor";
  readonly crashAt: number;
  readonly crashDraws: 1 | 2;
  /** Drawn only by a floor round; a crash round's script records null. */
  readonly jackpot: number;
  /** Drawn only by a floor round; a crash round's script records null. */
  readonly chests: readonly [number, number, number];
  /** The first creatures the world stream rolls (from draw 0), in spawn order. */
  readonly firstCreatures: readonly {
    readonly id: number;
    readonly kind: string;
    readonly x: number;
    readonly worldY: number;
    readonly size: number;
    readonly phase: number;
    readonly dir: 1 | -1;
  }[];
  /** RoundScript digest CANDIDATE (not owner-approved), or null when none is pinned. */
  readonly digestCandidate: string | null;
}

